# coding: utf-8
from lesson_authoring import entry as E
B=[['拉丁语 brevis','短的'],['法语 bref／brief → 英语 brief','短暂、简短；也有简要文书义']]
D=B+[['英语 brief 作动词','向人交代要点、背景或任务']]
AB=[['拉丁 brevis → abbreviare','短 → 使变短'],['拉丁 abbreviatus → 英语 abbreviate','缩短、缩写；具体英语形成亦有逆构分析']]
W=[
E('brief','/briːf/','短暂的、简短的；任务说明；向……交代情况','时间不长、内容不多；把必要信息压缩成抓得住的要点。','与拉丁 brevis“短”有关；形容词和文书名词有相关借入路线，动词由名词发展。',B,'a brief visit 是短暂来访，a brief explanation 是简短解释。工作里 a design brief 是设计任务要求，不只是“短短一段话”；brief the team 是把团队需要知道的要点交代清楚。词根给出“短”的中心，但任务说明也可能相当详细。','a brief pause；keep it brief；a project brief；brief someone on something。','brief 强调短，concise 强调简洁而不啰嗦。短文也可能写得含糊，brief 不保证写得好。',('We had a brief conversation outside the office.','我们在办公室外简短聊了几句。'),('The manager briefed the team on the new schedule.','经理向团队说明了新的时间安排。'),('Please read the design brief before starting.','开始前请先阅读设计任务说明。'),sources=['https://www.etymonline.com/word/brief','https://en.wiktionary.org/wiki/brief']),
E('briefly','/ˈbriːfli/','简短地；短暂地','给一个动作设定很小的时间或篇幅，不展开太久。','brief + -ly；对应“短暂”和“简短”两个常用方向。',B+[['brief + -ly → briefly','时间短；表达简短']],'speak briefly 是简短发言，stop briefly 是短暂停留。Briefly, ... 放在句首也可表示“简而言之”。判断时看它修饰的是持续时间还是信息表达，不必每次都译成“简要地”。','briefly explain；pause briefly；briefly mention。','briefly 是短时间或简短地；quickly 是速度快或很快发生。说得快不代表说得短。',('Could you briefly explain what happened?','你能简短说明发生了什么吗？'),('The lights went out briefly during the storm.','暴风雨期间，灯短暂熄灭了一会儿。'),sources=['https://en.wiktionary.org/wiki/briefly']),
E('brevity','/ˈbrevəti/','简短、简洁；短暂','把“短”本身当作一种性质来谈，常赞赏表达不拖沓。','来自拉丁 brevitas，可能经法语路线进入；保留 brev-，不是现代英语给 brief 直接加字母拼出来。',[['拉丁 brevis → brevitas','短 → 简短这一性质'],['英语 brevity','简洁；持续时间短']],'for brevity 是“为简洁起见”。The brevity of the meeting 只说会议短，未必评价它好坏；赞赏文字 brevity 时，则常看重用少量文字把意思讲清。这个词在写作评论中比日常说 shortness 更自然。','for brevity；brevity and clarity；the brevity of something。','brevity 是短这一性质；brief 是形容词或名词。simplicity 是简单，简短的内容也可能很复杂。',('For brevity, I have left out the technical details.','为简洁起见，我省去了技术细节。'),('The brevity of her answer surprised everyone.','她的回答如此简短，让所有人都有些意外。'),sources=['https://en.wiktionary.org/wiki/brevity','https://www.etymonline.com/word/brevity']),
E('briefing','/ˈbriːfɪŋ/','情况介绍；任务交代；简报会','在行动前或情况更新时，把大家需要掌握的重点集中讲清。','动词 brief + -ing，形成说明情况这一活动的名词。',D+[['brief + -ing → briefing','介绍背景、交代任务的活动']],'a safety briefing 是介绍安全注意事项；a press briefing 是向媒体说明情况。它既能指一场会议，也能指一段介绍，重点是传递必要信息。并非所有 briefing 都很短，也不一定只在任务开始前发生。','attend a briefing；a safety briefing；a press briefing；a briefing on the situation。','meeting 范围宽，可以讨论、谈判；briefing 更突出把信息和要点告诉参与者。',('Passengers listened to a safety briefing before boarding the boat.','乘客上船前听取了安全事项介绍。'),('The director gave a briefing on the project’s progress.','负责人介绍了项目进展。'),sources=['https://en.wiktionary.org/wiki/briefing','https://www.etymonline.com/word/brief']),
E('briefed','/briːft/','已被告知要点的；brief 的过去式和过去分词','任务相关的信息已经交代过，这个人不再毫无准备。','brief + -ed；词尾 /f/ 后的 -ed 读 /t/，不另加一个音节。',D+[['brief + -ed → briefed','已经向人说明；已经听取情况介绍']],'be briefed on something 是听取某方面的情况介绍，表示有人把要点告诉了你。它不保证你已经精通，也不等于参与了决策，只说明获得了相关说明。','be briefed on the plan；fully briefed；briefed in advance。','informed 泛指获知消息，briefed 更容易联想到为某项工作专门交代背景和要点。',('All volunteers were briefed on the route before the event.','活动开始前，所有志愿者都听取了路线说明。'),('I haven’t been briefed on the latest changes yet.','还没有人向我说明最新的变化。'),sources=['https://en.wiktionary.org/wiki/briefed','https://www.etymonline.com/word/brief']),
E('briefer','英 /ˈbriːfə/；美 /ˈbriːfər/','更短的、更简短的；作情况介绍的人','同一个词尾 -er 有两种任务：比较长度，或指做简报的人。','形容词 brief + 比较级 -er；另有动词 brief + 人员后缀 -er。',D+[['brief + -er 的两种构词','更简短；负责介绍情况的人']],'a briefer explanation 是更简短的解释，是日常更值得先掌握的用法。The briefer answered questions 则把 briefer 当人，指说明情况的发言者。看它修饰名词还是自己充当人物，通常就能分清。','a briefer version；a briefer reply；the official briefer。','briefer 可以是比较级，也可以是人员名词；不能看见 -er 就自动翻成“……的人”。',('Could you give me a briefer version of the story?','你能给我讲一个更简短的版本吗？'),('The briefer answered a few questions after the presentation.','介绍情况的人在说明结束后回答了几个问题。'),sources=['https://en.wiktionary.org/wiki/briefer']),
E('briefcase','/ˈbriːfkeɪs/','公文包','把 brief 理解为文件，再加上装文件的 case，就能看到公文包的用途。','brief“文书、文件” + case“箱、包”；不是因为包特别短小才叫 briefcase。',B+[['brief“文件” + case → briefcase','装文件的手提包']],'briefcase 通常是供工作携带文件等物品的包。它可以是硬壳，也可以是软质，现代也可能装电脑。名称保留的是“装公文”的用途，不要求外观永远固定。','a leather briefcase；carry a briefcase；put papers in a briefcase。','suitcase 是行李箱，briefcase 是公文包；二者都有 case，但用途不同。',('He put the signed documents in his briefcase.','他把签好的文件放进了公文包。'),('She left her briefcase under the desk.','她把公文包放在了桌子下面。'),sources=['https://www.etymonline.com/word/briefcase','https://en.wiktionary.org/wiki/briefcase']),
E('debrief','/diːˈbriːf/','听取任务后的汇报；事后复盘','行动结束后，把经历、结果和问题从参与者那里收集回来。','de- + brief，现代英语构词；可用任务前交代、任务后回收信息的对照帮助记忆，不是“撤销简报”。',D+[['de- + brief → debrief','任务后询问经过、收集信息']],'debrief the team 是听取团队的事后情况，常为了知道发生了什么、哪里需要改进。今天团队也会说 Let’s debrief，意思是一起复盘。它不必是一场审问，正常学习和改进也可以做 debrief。','debrief the team；debrief after an exercise；debrief participants。','brief 常向参与者交代信息；debrief 常在事后收集信息。两者是典型场景对照，不是每个具体用例都严格限定时间。',('The coordinator debriefed the volunteers after the festival.','节庆结束后，协调员听取了志愿者的情况汇报。'),('Let’s debrief tomorrow while the details are still fresh.','趁细节还记得清楚，我们明天复盘一下吧。'),sources=['https://www.etymonline.com/word/debrief','https://en.wiktionary.org/wiki/debrief']),
E('debriefing','/diːˈbriːfɪŋ/','事后汇报；复盘会','把任务后的回顾与信息收集，作为一场具体活动来安排。','debrief + -ing，相关活动名词；历史上这个名词形式在 debrief 的早期记录中就已出现。',D+[['debrief／debriefing','收集任务后的信息；事后复盘']],'复盘可以同时回顾做得好的和出问题的地方。活动可能短，也可能很详细，不能把词根“短”当成强制时长。重点是把刚发生的经历整理成可用信息。','a debriefing session；hold a debriefing；after the debriefing。','briefing 常是情况说明，debriefing 常是行动后的回顾；feedback 是反馈，范围更宽。',('The team held a short debriefing after the exercise.','演练结束后，团队进行了简短复盘。'),('During the debriefing, each volunteer described one problem they had noticed.','复盘时，每位志愿者都说了一个自己注意到的问题。'),sources=['https://en.wiktionary.org/wiki/debriefing','https://www.etymonline.com/word/debrief']),
]
